        'finding.camMicSuspicious' = '{0} used the {1}. That is a program worth a closer look.'
        'advice.camMicSuspicious'  = 'A remote-access tool or a program from Downloads using the camera or microphone can mean someone was watching or listening. Ask the client, and choose F2 for remote-access tools.'
        'steps.camMicSuspicious'   = 'Ask the client whether they know the program and used it for a call. | Unknown? Choose F2 to check for remote-access tools and remove them. | Then in the privacy fixes: switch camera or microphone off for that program.'
        'finding.camMicInUse'      = '{0} is using the {1} right now.'
        'advice.camMicInUse'       = 'Normal during a video call. If no call is going on, close that program; Windows also shows a camera or microphone icon in the taskbar while it is in use.'
        'steps.camMicInUse'        = 'Is a video call or recording going on? Then this is normal. | Not? Close the program, and check in the privacy fixes which programs may use it.'
        'finding.camMicOk'         = 'Only programs you would expect used the camera or microphone.'
        'advice.camMicOk'          = 'The list shows which programs used them and when. The privacy fixes switch access off per program.'
        'steps.camMicOk'           = 'Go through the list with the client: are these the programs they use for calls? | To be sure: in the privacy fixes, switch access off for programs that do not need it.'
        'finding.camMicNone'       = 'No app has used the camera or microphone on this PC.'
        'advice.camMicNone'        = 'Nothing has watched or listened in. For a video call that does not work, choose B2.'
        'steps.camMicNone'         = 'Camera or microphone not working in a call? Choose B2.'
        'finding.photosNoBackup'   = 'The {0} photos and videos are only on this PC: there is no backup.'
        'advice.photosNoBackup'    = 'If this PC breaks or is stolen, the photos are gone. Set up OneDrive folder backup (Windows Backup), or copy them to a USB drive, and repeat that now and then.'
        'steps.photosNoBackup'     = 'Choose the fix to open Settings > Backup and switch on backing up Pictures to OneDrive (needs a Microsoft account; 5 GB free). | Or copy the Pictures folder to a USB drive (choose the fix to open it), and keep that drive somewhere else. | Agree with the client how often to repeat it, for example every month.'
        'finding.photosOneDriveBroken' = 'Pictures ({0} photos and videos) is in the OneDrive folder, but OneDrive is not backing it up.'
        'advice.photosOneDriveBroken'  = 'The folder looks backed up but is not. Start or sign in to OneDrive again (G2 helps), or copy the photos to a USB drive first.'
        'steps.photosOneDriveBroken'   = 'First copy the Pictures folder to a USB drive, to be safe. | Choose G2: it checks OneDrive and starts it again. | OneDrive no longer wanted? Move the folders back: right-click Pictures > Properties > Location > Restore default.'
        'finding.photosBackedUp'   = 'The photos are backed up.'
        'advice.photosBackedUp'    = 'Check now and then that it still works: open OneDrive online, or the backup drive, and look for a recent photo.'
        'steps.photosBackedUp'     = 'Show the client where the backup is (onedrive.live.com, or the USB drive). | Look for a recent photo there to be sure it is up to date.'
        'finding.photosNone'       = 'There are no photos or videos in the Pictures folder.'
        'advice.photosNone'        = 'Maybe they are somewhere else: on the phone, in Downloads, or on a USB stick. G3 helps to find files.'
        'steps.photosNone'         = 'Ask the client where their photos usually are (phone, camera, USB stick). | Choose G3 to find files. | On an Android phone: the phone tab can check whether Google Photos backs them up.'
        'finding.linksOldBrowser'  = 'Links open in Internet Explorer, which no longer works properly.'
        'advice.linksOldBrowser'   = 'Set Edge or Chrome as the default browser in Default apps.'
        'steps.linksOldBrowser'    = 'Choose the fix to open Default apps. | Click Microsoft Edge (or Chrome) > Set default.'
        'finding.mailLinksRetired' = 'Email links open in {0}, the old Mail app, which stopped working at the end of 2024.'
        'advice.mailLinksRetired'  = 'Set the program the client really uses for email (Outlook, or the browser for Gmail and Ziggo webmail) in Default apps.'
        'steps.mailLinksRetired'   = 'Ask the client how they read email: Outlook, or a website (Gmail, Outlook.com, Ziggo, KPN)? | Choose the fix to open Default apps, search for "mailto", and pick that program (for a website: the browser). | Email itself not working? Choose A4.'
        'finding.linksNoBrowser'   = 'No program is set for web links.'
        'advice.linksNoBrowser'    = 'Then links in emails and documents may do nothing. Set a default browser.'
        'steps.linksNoBrowser'     = 'Choose the fix to open Default apps. | Click Microsoft Edge (or Chrome) > Set default.'
        'finding.mailLinksNone'    = 'No program is set for email links.'
        'advice.mailLinksNone'     = 'Clicking an email address on a website then does nothing. Fine if the client only uses webmail; otherwise set Outlook.'
        'steps.mailLinksNone'      = 'Choose the fix to open Default apps and search for "mailto". | Pick the program the client uses for email.'
        'finding.linksOk'          = 'Web and email links open in a program that is set.'
        'advice.linksOk'           = 'Is that the program the client wants? Change it in Default apps.'
        'steps.linksOk'            = 'Ask the client whether links should open in this browser and email program. | To change: choose the fix to open Default apps.'
        'finding.screenNotSeen'    = 'Windows sees only one screen.'
        'advice.screenNotSeen'     = 'The second screen or TV is not found: usually the cable, or the TV is on the wrong input (HDMI 1, HDMI 2).'
        'steps.screenNotSeen'      = 'Check that the cable is pushed in firmly at both ends, and try another cable or port. | On the TV: press Source or Input on the remote and pick the HDMI port the cable is in. | Press Windows key + P and choose Extend or Duplicate. | Choose the fix to open Settings > Display and click Detect (under Multiple displays).'
        'finding.screensOneDesktop' = 'Windows sees both screens, but shows one desktop.'
        'advice.screensOneDesktop'  = 'Both show the same picture, or only one is used. Choose Extend for two desktops, or Duplicate for the same picture (handy for a TV).'
        'steps.screensOneDesktop'   = 'Choose one of the fixes above, or press Windows key + P. | Extend: two desktops side by side. Duplicate: the same picture on both.'
        'finding.screensExtended'  = 'Both screens are in use as one big desktop.'
        'advice.screensExtended'   = 'Is the TV still black? Check its input. Windows key + Shift + arrow moves a window to the other screen.'
        'steps.screensExtended'    = 'TV or screen black? Choose the right input on it (Source, HDMI). | Move a window: Windows key + Shift + left or right arrow. | The same picture on the TV: choose the Duplicate fix.'
