        'finding.touchpadNotFound' = 'Windows does not see a touchpad on this laptop.'
        'advice.touchpadNotFound'  = 'Often it is switched off with a key: on most laptops Fn together with one of F1 to F12 (the key with a touchpad picture). Otherwise the driver is missing: Windows Update or the maker''s website has it.'
        'steps.touchpadNotFound'   = 'Look on F1 to F12 for a key with a touchpad picture; press it together with Fn. | Some laptops have a small light in the corner of the touchpad: double-tap there. | Still nothing? Settings > Windows Update > Advanced options > Optional updates > Driver updates. | Or the maker''s website: the touchpad driver for this exact model.'
        'finding.touchpadDisabled' = '{0} is switched off in Device Manager.'
        'advice.touchpadDisabled'  = 'Choose the fix below to switch it on again (needs an administrator window).'
        'steps.touchpadDisabled'   = 'Choose the fix above, or: right-click Start > Device Manager > Mice and other pointing devices. | Right-click the touchpad > Enable device.'
        'finding.touchpadError'    = '{0} reports a problem.'
        'advice.touchpadError'     = 'Restarting the device often helps; otherwise a new driver from Windows Update or the maker.'
        'steps.touchpadError'      = 'Choose the fix above to restart the touchpad (administrator window). | Still not working? Restart the laptop. | Then Windows Update > Optional updates > Driver updates.'
        'finding.touchpadOff'      = 'The touchpad is switched off in Settings.'
        'advice.touchpadOff'       = 'Open Settings > Touchpad and switch it on. On many laptops a key (Fn and a touchpad key) switches it too.'
        'steps.touchpadOff'        = 'Choose the fix to open Settings > Touchpad (with a mouse, or the Tab and space keys). | Switch Touchpad on. | Show the client the Fn key with the touchpad picture, so they know how it went off.'
        'finding.touchpadOffWithMouse' = 'The touchpad switches itself off while a mouse is connected.'
        'advice.touchpadOffWithMouse'  = 'Handy for some, confusing for others: with a mouse plugged in, the touchpad does nothing. Switch it off in Settings > Touchpad if the client uses both.'
        'steps.touchpadOffWithMouse'   = 'Choose the fix to open Settings > Touchpad. | Open the Touchpad section and tick "Leave touchpad on when a mouse is connected".'
        'finding.touchpadOk'       = 'The touchpad is found and switched on.'
        'advice.touchpadOk'        = 'Still nothing? Clean it (a dry cloth), check the Fn key, and restart the laptop.'
        'steps.touchpadOk'         = 'Wipe the touchpad with a dry cloth; wet fingers also make it jumpy. | Try the Fn key with the touchpad picture. | Restart the laptop and try again.'
