        'fix.privateDnsAuto'        = 'Set private DNS to Automatic instead of {0}'
        'fix.privateDnsAuto.done'   = 'Set private DNS on the phone to Automatic instead of {0}'
        'fix.phoneOpenStorage'      = 'Open Storage on the device''s screen'
        'fix.phoneOpenStorage.done' = 'Opened Storage on the phone'
        'fix.phoneOpenBattery'      = 'Open Battery on the device''s screen'
        'fix.phoneOpenBattery.done' = 'Opened Battery on the phone'
        'fix.phoneOpenUpdates'      = 'Open Software update on the device''s screen'
        'fix.phoneOpenUpdates.done' = 'Opened Software update on the phone'
        'fix.phoneDebugOff'         = 'Done with {0}: switch USB and Wireless debugging off again'
        'fix.phoneDebugOff.done'    = 'Switched USB and Wireless debugging off again on {0}'
        'problem.M8' = 'Connect over Wi-Fi (car screen, or a tablet without its cable)'
        'pair.ask'     = 'On the device: Developer options > Wireless debugging > Pair device with pairing code, and keep that window open. Type the 6-digit code (Housecall finds the device itself; if it does not, type the address with the port and the code, e.g. 192.168.1.50:41235 482915)'
        'pair.invalid' = '"{0}" is not a 6-digit code, or an address with a port and a code like 192.168.1.50:41235 482915 (or only the address and port, to connect).'
        'and.pairNotFound'       = 'No device with an open pairing window found on this Wi-Fi'
        'finding.pairNotFound'   = 'Housecall could not find a device with an open pairing window on this Wi-Fi.'
        'advice.pairNotFound'    = 'Keep the pairing window open on the device and check that this laptop is on the same Wi-Fi. Some networks block the search: then type the address with the port and the code from the pairing window.'
        'steps.pairNotFound'     = 'On the device: Developer options > Wireless debugging > Pair device with pairing code, and keep that window open. | Check that this laptop and the device are on the same Wi-Fi (for a car screen: the same phone hotspot). | Choose M8 again and type the code. | Still not found? Type the address with the port and the code from the pairing window, e.g. 192.168.1.50:41235 482915.'
        'and.paired'         = 'Paired with {0}'
        'and.pairFailed'     = 'Pairing with {0} failed: {1}'
        'and.pairedNoDevice' = 'Paired, but the device did not show up on the network'
        'and.connectFailed'  = 'Could not connect to {0}: {1}'
        'and.wifiConnected'  = 'Connected over Wi-Fi'
        'finding.pairFailed'      = 'Pairing over Wi-Fi did not work.'
        'advice.pairFailed'       = 'The code only works while the pairing window is open on the device, and only once. Open it again and type the new address and code.'
        'steps.pairFailed'        = 'On the device: Developer options > Wireless debugging: is it on? | Tap Pair device with pairing code and keep that window open. | Check that this laptop and the device are on the same Wi-Fi (for a car screen: the same phone hotspot). | Type the address with the port and the new code, and run this check again.'
        'finding.pairedNoConnect' = 'Pairing worked, but the device did not show up on the network.'
        'advice.pairedNoConnect'  = 'Type the address and port shown on the Wireless debugging screen itself (not the pairing window): that connects it directly.'
        'steps.pairedNoConnect'   = 'Close the pairing window on the device. | Look at the Wireless debugging screen: it shows IP address and port, for example 192.168.1.50:38497. | Choose M8 again and type only that address with the port, without a code.'
        'finding.connectFailed'   = 'Connecting over Wi-Fi did not work.'
        'advice.connectFailed'    = 'Usually Wireless debugging is off, the port has changed, or the device is not paired yet. The port changes every time Wireless debugging is switched on.'
        'steps.connectFailed'     = 'On the device: Developer options > Wireless debugging: switch it on. | Check that this laptop and the device are on the same Wi-Fi. | Not paired yet with this laptop? Tap Pair device with pairing code and type the address and code. | Paired already: type the IP address and port from the Wireless debugging screen.'
        'fix.note.adb'         = '(about 8 MB from Google, signature checked, kept in Housecall''s own folder; can be undone)'
        'fix.note.phoneScreen' = '(opens on the device''s screen, changes nothing)'
        'fix.note.debugOff'    = '(the device disconnects from this laptop; switch it on again in Developer options when needed)'

        'finding.adbMissing'      = 'Google''s free Android tool (ADB) is not on this laptop yet. Housecall reads a phone through it.'
        'advice.adbMissing'       = 'Choose the fix below: Housecall downloads it from Google once and checks Google''s signature. It stays in Housecall''s own folder and undo removes it again.'
        'steps.adbMissing'        = 'Choose the fix above to download the tool. | Then connect the phone with a USB cable and run this check again.'
        'finding.phoneNotFound'   = 'No phone or tablet answers on the USB cable.'
        'advice.phoneNotFound'    = 'Windows does not see a known phone on the cable either. Try another cable (some cables only charge), and switch on USB debugging once: the steps below show how.'
        'steps.phoneNotFound'     = 'On the phone: Settings > About phone > Software information, and tap Build number 7 times until it says you are now a developer. | Go back to Settings: Developer options is now there (often at the bottom, or under System). | Switch on USB debugging and confirm. | Connect the phone to this laptop with a USB cable that carries data (the one that came with the phone is best). | Unlock the phone. It asks: Allow USB debugging? Tick Always allow from this computer and tap Allow. | Run this check again.'
        'finding.phoneUnauthorized' = 'The phone is connected, but has not allowed this laptop yet.'
        'advice.phoneUnauthorized'  = 'Unlock the phone and look for the question "Allow USB debugging?". Tap Allow, then run this check again.'
        'steps.phoneUnauthorized'   = 'Unlock the phone. | Look for the question Allow USB debugging? on its screen (pull the notifications down if it is not there). | Tick Always allow from this computer and tap Allow. | No question at all? Unplug the cable and plug it in again. | Run this check again.'
        'finding.phoneOffline'    = 'The phone is connected, but does not answer.'
        'advice.phoneOffline'     = 'Unplug the cable and plug it in again with the phone unlocked. If that does not help, switch USB debugging off and on in Developer options.'
        'steps.phoneOffline'      = 'Unplug the USB cable, unlock the phone, and plug it in again. | Still nothing? Settings > Developer options: switch USB debugging off and on again. | Try another USB port or cable. | Run this check again.'
        'finding.phoneOverviewOk' = 'The device is in good shape: nothing found that needs attention.'
        'advice.phoneOverviewOk'  = 'Has the client a specific complaint, such as slow or a battery that runs out? Choose that check in this group.'
        'steps.phoneOverviewOk'   = 'Note the model and Android version for the client. | Choose another M check if there is a specific complaint. | Done? Choose the fix to switch USB debugging off again.'
        'finding.phoneStorageFull' = 'The storage is almost full: only {0} free. Apps get slow, updates fail and photos cannot be saved.'
        'advice.phoneStorageFull'  = 'Free up space: usually photos and videos (copy them to a computer, or check Google Photos has them) and apps no longer used. M3 shows what takes the space.'
        'steps.phoneStorageFull'   = 'Choose M3 to see what takes the space. | Photos and videos: copy them to a computer or USB stick, or check that Google Photos has backed them up, then delete them from the phone. | Apps no longer used: Settings > Apps, choose the app, Uninstall. | WhatsApp: Settings > Storage and data > Manage storage shows the big chats and videos. | Restart the phone afterwards.'
        'finding.phoneStorageLow'  = 'The storage is getting full: {0} free.'
        'advice.phoneStorageLow'   = 'Nothing urgent, but clearing old photos, videos and unused apps now prevents problems later.'
        'steps.phoneStorageLow'    = 'Choose M3 to see what takes the space. | Copy photos and videos to a computer, or check that they are backed up. | Uninstall apps that are no longer used.'
        'finding.phoneStorageOk'   = 'There is enough free storage.'
        'advice.phoneStorageOk'    = 'Nothing to do here.'
        'steps.phoneStorageOk'     = 'Nothing to do: there is enough space. | Done? Choose the fix to switch USB debugging off again.'
        'finding.phoneMemoryFull'  = 'Almost all memory is in use right now.'
        'advice.phoneMemoryFull'   = 'Restarting the phone clears the memory. Apps open in the background use it too.'
        'steps.phoneMemoryFull'    = 'Restart the phone: hold the power button and choose Restart. | Afterwards, close apps that are not needed: the square or three-line button at the bottom, then Close all. | Still slow? Choose M3: a full storage slows the phone down too.'
        'finding.phoneLowRam'      = 'This device has little memory: {0} in total. That is why heavy apps such as Google Maps are slow on it.'
        'advice.phoneLowRam'       = 'Memory cannot be added to a phone or car screen. Keep few apps open, or on a car screen show the phone instead (Android Auto).'
        'steps.phoneLowRam'        = 'Keep as few apps open as possible. | Uninstall apps that start by themselves and are not needed. | On a car screen: use Android Auto or screen mirroring from the phone instead of apps on the screen itself. | For a phone: if it stays too slow, a newer phone is the real fix.'
        'finding.phoneLongUptime'  = 'The device has not been restarted for {0} days.'
        'advice.phoneLongUptime'   = 'A restart clears the memory and finishes waiting updates. Once a week is good.'
        'steps.phoneLongUptime'    = 'Hold the power button and choose Restart. | Check afterwards whether it feels faster.'
        'finding.phoneSpeedOk'     = 'Nothing found that makes the device slow: storage, memory and restarts are fine.'
        'advice.phoneSpeedOk'      = 'Slow in one app only? Update that app in the Play Store, or clear its temporary files: Settings > Apps > the app > Storage > Clear cache.'
        'steps.phoneSpeedOk'       = 'Update all apps: Play Store > profile picture > Manage apps and device > Update all. | Slow in one app: Settings > Apps > the app > Storage > Clear cache (this keeps the data). | Restart the phone.'
        'finding.androidOld'       = 'Android {0} is old. More and more apps, banking apps first, stop working on it.'
        'advice.androidOld'        = 'Check Software update once. If nothing comes, this device cannot be updated any more: advise the client about a newer one for banking and email.'
        'steps.androidOld'         = 'Choose the fix to open Software update on the device. | Download and install what is there. | Nothing new? Then this is the last Android for this device. | Advise the client: fine for simple things, a newer phone for banking.'
        'finding.phonePatchOld'    = 'The last security update is {0} months old. The maker no longer updates this device.'
        'advice.phonePatchOld'     = 'It still works, but is not protected against new attacks. Banking on it is a risk; a newer device is the safe choice.'
        'steps.phonePatchOld'      = 'Choose the fix to open Software update and check once more. | Nothing new? The maker has stopped updating it. | Advise the client: no banking or payments on this device.'
        'finding.phonePatchStale'  = 'The last security update is {0} months old.'
        'advice.phonePatchStale'   = 'There is probably an update waiting. Install it with the phone charged and on Wi-Fi.'
        'steps.phonePatchStale'    = 'Plug the charger in and connect to Wi-Fi. | Choose the fix to open Software update on the device. | Download and install. The phone restarts by itself. | Run this check again.'
        'finding.phoneUpdatesOk'   = 'Android is up to date: the last security update is recent.'
        'advice.phoneUpdatesOk'    = 'Nothing to do. Updating the apps in the Play Store is still worth a look.'
        'steps.phoneUpdatesOk'     = 'Play Store > profile picture > Manage apps and device > Update all. | Done? Choose the fix to switch USB debugging off again.'
        'finding.phoneBatteryBad'  = 'The battery reports a fault: {0}.'
        'advice.phoneBatteryBad'   = 'This is hardware. Stop charging it if it is hot or swollen, and have the battery replaced.'
        'steps.phoneBatteryBad'    = 'Feel the back: hot, or is it bulging? Then stop charging and do not use it. | Note the model and look up the cost of a new battery. | Replace the battery, or advise a new device if the phone is old.'
        'finding.phoneHot'         = 'The battery is hot: {0} degrees.'
        'advice.phoneHot'          = 'Take it off the charger and out of the sun, close heavy apps, and let it cool down. Often hot again? The battery may be worn.'
        'steps.phoneHot'           = 'Unplug the charger and take off a thick case. | Close the apps that are open. | Let it cool for 15 minutes, then run this check again.'
        'finding.phoneNotCharging' = 'The charger is connected, but the battery is not charging ({0}%).'
        'advice.phoneNotCharging'  = 'Usually the cable, the charger, or lint in the charging port. Try another cable and charger, and clean the port carefully.'
        'steps.phoneNotCharging'   = 'Try another cable and another charger. | Look into the charging port with a light: lint? Remove it carefully with a wooden toothpick, never metal. | Restart the phone and plug it in again. | Still not charging? The port or the battery needs repair.'
        'finding.phoneBatteryWorn' = 'The battery has been charged {0} times. Most batteries are worn after about 800.'
        'advice.phoneBatteryWorn'  = 'A worn battery runs out fast. Replacing it is often much cheaper than a new phone.'
        'steps.phoneBatteryWorn'   = 'Settings > Battery (or Device care) shows the condition on many phones. | Look up the price of a new battery for this model. | Plan the replacement as a separate job.'
        'finding.phoneScreenLong'  = 'The screen stays on for a long time when the phone is not used.'
        'advice.phoneScreenLong'   = 'A screen that stays on uses the most power. Set it to turn off after 30 seconds or 1 minute.'
        'steps.phoneScreenLong'    = 'Settings > Display > Screen timeout. | Choose 30 seconds or 1 minute. | Also: Settings > Display > Brightness on automatic.'
        'finding.phoneBatteryOk'   = 'The battery looks healthy.'
        'advice.phoneBatteryOk'    = 'Runs out fast anyway? The screen and apps running in the background use the most. Settings > Battery shows which ones.'
        'steps.phoneBatteryOk'     = 'Choose the fix to open Battery on the device and see which apps use the most. | Lower the brightness, or set it to automatic. | Switch on battery saver when it is low.'
        'finding.airplaneOn'       = 'Airplane mode is on: Wi-Fi and mobile internet are off.'
        'advice.airplaneOn'        = 'Swipe down from the top of the screen and tap the airplane icon to switch it off.'
        'steps.airplaneOn'         = 'Swipe down from the top of the screen. | Tap the airplane icon so it is no longer lit. | Run this check again.'
        'finding.phoneNoNetwork'   = 'Wi-Fi and mobile data are both off, so the device has no internet.'
        'advice.phoneNoNetwork'    = 'Switch on Wi-Fi (at home) or mobile data (on the road) in the quick settings at the top of the screen.'
        'steps.phoneNoNetwork'     = 'Swipe down from the top of the screen. | Tap Wi-Fi and choose the home network. | On the road: tap Mobile data. | Run this check again.'
        'finding.phoneNoInternet'  = 'The device is connected, but does not reach the internet.'
        'advice.phoneNoInternet'   = 'Check the Wi-Fi on another device. Works there? Forget the network on this device and connect again. On mobile data: check that the bundle is not used up.'
        'steps.phoneNoInternet'    = 'Check whether the internet works on another device on the same Wi-Fi. | On this device: Settings > Wi-Fi, tap the network, Forget, and connect again with the password. | On mobile data: check the bundle in the provider''s app. | Restart the device and run this check again.'
        'finding.privateDnsBroken' = 'Website names do not work because private DNS is set to {0}, which does not answer.'
        'advice.privateDnsBroken'  = 'Choose the fix below: private DNS goes back to Automatic. It can be undone.'
        'steps.privateDnsBroken'   = 'Choose the fix above, or: Settings > Connections (or Network and internet) > More connection settings > Private DNS. | Choose Automatic. | Run this check again.'
        'finding.phoneDnsFail'     = 'The internet answers, but website names do not work.'
        'advice.phoneDnsFail'      = 'Usually the router or the Wi-Fi. Forget the network and connect again, or restart the router.'
        'steps.phoneDnsFail'       = 'Settings > Wi-Fi: tap the network, Forget, and connect again. | Restart the router: plug it out, wait 30 seconds, plug it in. | Run this check again.'
        'finding.phoneClockWrong'  = 'The date or time on the device is {0} off. Google sign-in and many apps refuse to connect because of that.'
        'advice.phoneClockWrong'   = 'Switch on automatic date and time, so the device sets itself from the network. Then sign in again.'
        'steps.phoneClockWrong'    = 'Choose the fix to switch on automatic date and time, or: Settings > General management (or System) > Date and time. | Switch on Automatic date and time and Automatic time zone. | Already on but still wrong? Connect to the internet first: the clock is set from the network. | Sign in to Google again.'
        'finding.phoneAutoTimeOff' = 'Automatic date and time is off. The clock drifts, and once it is far off, Google sign-in fails.'
        'advice.phoneAutoTimeOff'  = 'Choose the fix below to switch it on. It can be undone.'
        'steps.phoneAutoTimeOff'   = 'Choose the fix above, or: Settings > Date and time. | Switch on Automatic date and time.'
        'finding.phoneAutoZoneOff' = 'Automatic time zone is off.'
        'advice.phoneAutoZoneOff'  = 'Fine at home, but abroad the clock stays on Dutch time. Switching it on is safer.'
        'steps.phoneAutoZoneOff'   = 'Choose the fix above, or: Settings > Date and time. | Switch on Automatic time zone.'
        'finding.phoneOnlineOk'    = 'The connection, the date and the time are all right.'
        'advice.phoneOnlineOk'     = 'Google sign-in still fails? Check the password on another device at accounts.google.com, and update Google Play services in the Play Store.'
        'steps.phoneOnlineOk'      = 'Check the email address and password on another device at accounts.google.com. | Play Store: update Google Play services and Google. | Restart the device and try again.'
        'fix.phoneMirror'          = 'Show the screen of {0} on this laptop'
        'fix.phoneMirror.done'     = 'Showed the phone''s screen on the laptop'
        'fix.phoneScreenshot'      = 'Take a screenshot of {0}'
        'fix.phoneScreenshot.done' = 'Took a screenshot of the phone'
        'fix.phoneRestart'         = 'Restart {0}'
        'fix.phoneRestart.done'    = 'Restarted {0}'
        'fix.note.mirror'       = '(work it with mouse and keyboard; the first time it downloads the free program scrcpy, about 11 MB, fingerprint checked; close its window to stop)'
        'fix.note.screenshot'   = '(saved in Pictures\Housecall on this laptop, and opened)'
        'fix.note.phoneRestart' = '(takes about a minute; Housecall waits until the phone is back)'
        'and.screenshotFailed' = 'The phone did not make the screenshot. Unlock it and try again.'
        'and.restartSlow'      = 'The phone is not back after 3 minutes. Check that it started up and is unlocked, then run the check again.'
        'and.mirrorFailed'     = 'The phone''s screen could not be shown. Unlock the phone and try again.'
        'and.badHash'          = 'The download does not match the published fingerprint, so it was not kept.'
        'problem.M7' = 'Is there a virus or scam app on the phone?'
        'and.protectOff'     = 'Google Play Protect (the built-in virus scanner) is switched off'
        'and.protectOn'      = 'Google Play Protect is on'
        'and.outsideStrong'  = 'Not from an app store, and can read the screen, the messages or manage the phone: {0}'
        'and.accessApp'      = 'Can read and control the screen (Accessibility): {0}'
        'and.accessNone'     = 'No unknown apps can read the screen'
        'and.notifyApp'      = 'Can read all notifications, codes from the bank too: {0}'
        'and.notifyNone'     = 'No unknown apps can read the notifications'
        'and.remoteApp'      = 'Remote-access app installed: {0}'
        'and.remoteNone'     = 'No remote-access apps (AnyDesk, TeamViewer, RustDesk, AirDroid)'
        'and.adminApp'       = 'Device admin, so harder to remove: {0}'
        'and.adminNone'      = 'No unknown device admin apps'
        'and.outside'        = '{0} apps not installed from an app store: {1}'
        'and.outsideNone'    = 'Every app comes from an app store'
        'and.appsUnknown'    = 'The list of apps could not be read'
        'and.mayInstall'     = 'May install other apps by themselves: {0}'
        'and.mayInstallNone' = 'No app may install other apps by itself'
        'fix.phoneOpenApp'      = 'Open the page of {0} on the phone (to uninstall it there)'
        'fix.phoneOpenApp.done' = 'Opened the page of {0} on the phone'
        'fix.note.appPage'      = '(opens on the phone''s screen; Housecall itself removes nothing)'
        'finding.phoneMalwareLikely'    = '{0} was not installed from an app store and can read the screen, the messages or manage the phone. This is how banking malware works.'
        'advice.phoneMalwareLikely'     = 'No banking on this phone until it is gone. Open the app''s page below and uninstall it together with the client; then change the bank password from another device and call the bank.'
        'steps.phoneMalwareLikely'      = 'Choose the fix to open the app''s page on the phone. | Uninstall greyed out? Settings > Security > Device admin apps: switch the app off there first. | Uninstall the app. | Play Store > profile picture > Play Protect > Scan. | Call the bank on the number on the bank card, and change the banking password from another device.'
        'finding.phoneRemoteApp'        = 'A remote-access app is installed: {0}. With it, someone else can see and control the phone.'
        'advice.phoneRemoteApp'         = 'Ask the client who installed it. Did "the bank", "Microsoft" or a helpdesk ask them to? Then it is a scam: uninstall it and call the bank.'
        'steps.phoneRemoteApp'          = 'Ask the client whether they know the app and who asked them to install it. | Unknown, or installed for a caller: choose the fix to open its page and uninstall it. | Was a "bank" or "helpdesk" involved? Call the bank on the number on the bank card.'
        'finding.playProtectOff'        = 'Google Play Protect, the phone''s built-in virus scanner, is switched off.'
        'advice.playProtectOff'         = 'Scammers often tell people to switch it off first. Switch it on again and run a scan.'
        'steps.playProtectOff'          = 'Open the Play Store and tap the profile picture. | Play Protect > Settings (gear icon). | Switch on Scan apps with Play Protect. | Go back and tap Scan.'
        'finding.phoneAccessibilityApp' = '{0} can read and control the screen (Accessibility).'
        'advice.phoneAccessibilityApp'  = 'Sometimes on purpose (a password manager, a screen reader), but it is also how malware works. Ask the client whether they know it.'
        'steps.phoneAccessibilityApp'   = 'Ask the client whether they know the app and why it has this access. | Unknown? Settings > Accessibility > Installed apps: switch it off. | Then choose the fix to open its page and uninstall it.'
        'finding.phoneNotifyApp'        = '{0} can read all notifications, codes from the bank too.'
        'advice.phoneNotifyApp'         = 'A smartwatch app or a car app needs this; an unknown app does not.'
        'steps.phoneNotifyApp'          = 'Ask the client whether they know the app (a smartwatch app is normal). | Unknown? Settings > Notifications > Notification access (sometimes under Advanced settings): switch it off. | Then choose the fix to open its page and uninstall it.'
        'finding.phoneDeviceAdmin'      = '{0} is a device admin app, which makes it harder to remove.'
        'advice.phoneDeviceAdmin'       = 'Work phones use this; an unknown app should not. Ask the client whether the phone is from work.'
        'steps.phoneDeviceAdmin'        = 'Settings > Security (or Security and privacy) > Device admin apps (sometimes under Other security settings). | Switch the unknown app off. | Then choose the fix to open its page and uninstall it.'
        'finding.phoneUnknownSources'   = 'These apps may install other apps by themselves: {0}.'
        'advice.phoneUnknownSources'    = 'This is how a link in a text or WhatsApp message installs a fake app. Switch it off unless the client really needs it.'
        'steps.phoneUnknownSources'     = 'Settings > Apps > the app > Install unknown apps (on Samsung: Settings > Security > Install unknown apps). | Switch it off. | Do this for every app in the list.'
        'finding.phoneSideloaded'       = '{0} apps were not installed from an app store.'
        'advice.phoneSideloaded'        = 'Not wrong in itself, but most phone malware comes in this way. Go through the list with the client.'
        'steps.phoneSideloaded'         = 'Go through the names above with the client. | An app nobody recognises: choose the fix to open its page and uninstall it. | Afterwards: Play Store > profile picture > Play Protect > Scan.'
        'finding.phoneSafeOk'           = 'Nothing suspicious found: no unknown apps with access to the screen, the messages or the phone''s management.'
        'advice.phoneSafeOk'            = 'Still worried? Run a Play Protect scan, and tell the client that a bank never asks to install an app or to read out a code.'
        'steps.phoneSafeOk'             = 'Play Store > profile picture > Play Protect > Scan. | Tell the client: a bank never asks to install an app or to read out a code.'
        'and.cablePhone' = '{0} phone found on the USB cable'
        'and.debugOff'   = '{0} phone found on the cable, but USB debugging is off'
        'and.noDriver'   = '{0} phone found, but Windows has no driver for its debug connection'
        'and.iphone'     = 'An iPhone or iPad is on the cable: Housecall can only read Android devices'
        'finding.iphoneFound'   = 'This is an iPhone or iPad. Housecall can only read Android phones and tablets.'
        'advice.iphoneFound'    = 'On an iPhone, look on the phone itself: the steps below show where model, updates, battery and storage are.'
        'steps.iphoneFound'     = 'Settings > General > About: model and iOS version. | Settings > General > Software Update. | Settings > Battery > Battery Health and Charging. | Settings > General > iPhone Storage: what takes the space.'
        'finding.phoneNoDriver' = 'The {0} phone is on the cable with USB debugging on, but Windows has no driver for that connection.'
        'advice.phoneNoDriver'  = 'Windows Update usually has the driver under optional updates. Otherwise the maker offers a free USB driver.'
        'steps.phoneNoDriver'   = 'Settings > Windows Update > Advanced options > Optional updates > Driver updates: install the one for the phone. | Nothing there? Download the maker''s free USB driver (Samsung: Samsung Android USB Driver; Pixel: Google USB Driver). | Unplug the phone and plug it in again. | Run this check again.'
        'finding.phoneDebuggingOff'        = 'A {0} phone is on the cable, but USB debugging is not switched on yet.'
        'advice.phoneDebuggingOff'         = 'USB debugging is switched on once, on the phone itself: Android never lets a computer do that. The steps below show where.'
        'steps.phoneDebuggingOff'          = 'On the phone: Settings > About phone (sometimes under Software information). | Tap Build number 7 times, and enter the PIN when asked, until it says you are now a developer. | Go back to Settings: Developer options is now there (at the bottom, or under System). | Switch on USB debugging and confirm. | Unlock the phone. It asks: Allow USB debugging? Tick Always allow from this computer and tap Allow. | Run this check again.'
        'finding.phoneDebuggingOffSamsung' = 'A {0} phone is on the cable, but USB debugging is not switched on yet.'
        'advice.phoneDebuggingOffSamsung'  = 'USB debugging is switched on once, on the phone itself: Android never lets a computer do that. The steps below are for Samsung''s menus.'
        'steps.phoneDebuggingOffSamsung'   = 'On the phone: Settings > About phone > Software information. | Tap Build number 7 times, and enter the PIN when asked, until it says Developer mode has been turned on. | Go back to Settings and scroll to the very bottom: Developer options. | Switch on USB debugging and tap OK. | Unlock the phone. It asks: Allow USB debugging? Tick Always allow from this computer and tap Allow. | Run this check again.'
        'finding.phoneDebuggingOffPixel'   = 'A {0} phone is on the cable, but USB debugging is not switched on yet.'
        'advice.phoneDebuggingOffPixel'    = 'USB debugging is switched on once, on the phone itself: Android never lets a computer do that. The steps below are for a Pixel (other phones on Google''s USB number look much the same).'
        'steps.phoneDebuggingOffPixel'     = 'On the phone: Settings > About phone, and scroll to the bottom. | Tap Build number 7 times, and enter the PIN when asked, until it says You are now a developer. | Go back to Settings > System > Developer options. | Switch on USB debugging and tap OK. | Unlock the phone. It asks: Allow USB debugging? Tick Always allow from this computer and tap Allow. | Run this check again.'
        'finding.phoneDebuggingOffXiaomi'  = 'A {0} phone is on the cable, but USB debugging is not switched on yet.'
        'advice.phoneDebuggingOffXiaomi'   = 'USB debugging is switched on once, on the phone itself: Android never lets a computer do that. Xiaomi, Redmi and POCO hide it a little deeper; the steps below show where.'
        'steps.phoneDebuggingOffXiaomi'    = 'On the phone: Settings > About phone. | Tap OS version (or MIUI version) 7 times until it says You are now a developer. | Go back to Settings > Additional settings > Developer options. | Switch on USB debugging. For fixes that change a setting (such as the clock), also switch on USB debugging (Security settings); that one needs a SIM card and a Xiaomi account. | Unlock the phone. It asks: Allow USB debugging? Tick Always allow from this computer and tap Allow. | Run this check again.'
        'finding.phoneDebuggingOffOppo'    = 'A {0} phone is on the cable, but USB debugging is not switched on yet.'
        'advice.phoneDebuggingOffOppo'     = 'USB debugging is switched on once, on the phone itself: Android never lets a computer do that. The steps below are for OPPO, realme and OnePlus menus.'
        'steps.phoneDebuggingOffOppo'      = 'On the phone: Settings > About device > Version (on some: About phone). | Tap Build number 7 times, and enter the PIN when asked, until it says you are now in developer mode. | Go back to Settings > Additional settings (or System settings) > Developer options. | Switch on USB debugging. | Unlock the phone. It asks: Allow USB debugging? Tick Always allow from this computer and tap Allow. | Run this check again.'
    }

